using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "TidalJetCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Cellarius/TidalJetCustomDescription", order = 0)]
public class TidalJetCustomDescription : PurifyMinimunWaveCustomDescription
{
	protected override string GetExtraActionDescription(BattleAction battleAction, string amountModified)
	{
		TidalJetAction tidalJetAction = battleAction as TidalJetAction;
		return Smart.Format(GetRawLocalizedDescription(battleAction), amountModified, tidalJetAction.PurifiedLightningTimesAmount);
	}
}
